declare
  o uuid := (select id from public.profiles where handle = 'pinwith');
  doc jsonb := $json$[{"slug":"euljiro-nopo","title":"을지로·종로 노포 투어: 점심부터 막걸리까지","desc":"수십 년 같은 자리를 지킨 집들만 골랐어요. 점심에 냉면·곰탕으로 시작해 저녁엔 시장 골목에서 마무리합니다.\n섹션을 누르면 시간대별 장소만 지도에 보여요.","kind":"course","themes":["서울","노포","맛집","을지로"],"sections":[{"name":"점심","items":[["ChIJ95h3lR-jfDURkB9hKZltPXM",37.5681851,126.9987092,"우래옥","평양냉면 입문으로 좋은 집. 육수가 맑고 슴슴해요. 불고기도 같이 시켜 보세요.",["평양냉면"]],["ChIJvZjTMWC9fDURxnT8dx21N3U",37.5643946,126.9850185,"하동관","곰탕 하나로 오래 버틴 집. 국물이 떨어지면 오후 일찍 문을 닫으니 점심에 가세요.",["일찍 마감"]],["ChIJW7FBDfCifDURHTpisLbVUH0",37.5610151,126.9860829,"명동교자","칼국수와 만두. 마늘 김치가 아주 세고, 면·밥 추가는 무료예요.",["칼국수"]]]},{"name":"오후 산책","items":[["ChIJIwCT4-yifDUR1E63iG76hr0",37.5691015,126.9786692,"청계천","배 꺼트리기 좋은 물길 산책. 광장시장 쪽으로 동쪽으로 걸어가면 저녁 장소와 이어져요.",["산책","무료"]]]},{"name":"저녁","items":[["ChIJm3V0fu2ifDURRJ8IMUijVtY",37.5700385,126.9996038,"광장시장","빈대떡에 막걸리 한 잔. 육회와 마약김밥도 이 시장이 원조로 꼽혀요. 현금을 챙기세요.",["현금","빈대떡"]],["ChIJ_TLjgiSjfDURnctlL07vfJo",37.5703627,127.0057612,"닭한마리 골목","냄비째 끓여 먹는 닭 한 마리. 마지막은 칼국수 사리로.",["여럿이"]]]}]},{"slug":"anguk-walk","title":"안국 하루 산책: 궁궐, 한옥 골목, 베이글까지","desc":"지하철 3호선 안국역에서 걸어서 다 닿는 거리예요. 오전엔 궁, 점심 무렵 한옥 골목, 오후엔 카페와 익선동.","kind":"course","themes":["서울","산책","한옥","궁궐"],"sections":[{"name":"오전 · 궁궐","items":[["ChIJod7tSseifDUR9hXHLFNGMIs",37.579617,126.977041,"경복궁","한복을 입으면 입장 무료. 화요일 휴궁이에요.",["화 휴궁","한복 무료"]],["ChIJ4wh0zluifDURaFBW2pdrKf8",37.5794309,126.9910426,"창덕궁","경복궁보다 한적하고 숲이 좋아요. 후원은 따로 시간 예약하는 관람이에요. 월요일 휴궁.",["월 휴궁","후원 예약"]]]},{"name":"점심 무렵 · 한옥 골목","items":[["ChIJT8H4r9qifDURmuXJ_6m6vM0",37.5814696,126.9849519,"북촌 한옥마을","주민이 사는 동네예요. 정해진 관광 허용 시간을 지키고 조용히 다녀 주세요.",["조용히"]],["ChIJKw66zRCjfDURuaw9qYPdI-k",37.5791826,126.986152,"런던베이글뮤지엄 안국","오픈 전에 줄을 서거나 앱으로 대기 등록하는 게 빨라요.",["웨이팅"]]]},{"name":"오후 · 카페와 골목","items":[["ChIJLXL2BvijfDURmTrYFPQIGUc",37.5776235,126.9865541,"어니언 안국","한옥 마당 자리가 명당. 빵은 일찍 떨어지는 것도 있어요.",["한옥 카페"]],["ChIJR2GkpsKifDURh6X4t1FUx1Y",37.5732841,126.9856063,"인사동길","전통 찻집과 한지·공예품 가게. 기념품 고르기 좋아요.",["기념품"]],["ChIJe4Jbot2ifDUR2zWhruwyaow",37.5737132,126.9901271,"익선동","골목에 불이 켜지는 저녁이 가장 예뻐요.",["저녁"]]]}]},{"slug":"seoul-cafes","title":"서울 카페 지도: 동네별로 한 곳씩","desc":"동네마다 '여기는 가 볼 만하다' 싶은 카페만 골랐어요. 커피 맛, 공간, 빵 중 무엇이 좋은지 태그로 표시했어요.","kind":"collection","themes":["서울","카페","베이커리"],"sections":[{"name":"성수","items":[["ChIJ993jM5alfDURK3Yb1pmmBf8",37.5480352,127.0457013,"블루보틀 성수","블루보틀의 한국 1호점. 붉은 벽돌 건물, 핸드드립 추천.",["핸드드립"]],["ChIJHb1ypJWkfDURb2d4XCjLluM",37.5447328,127.0582091,"어니언 성수","오래된 공장을 그대로 살린 공간. 팡도르가 대표 빵이에요.",["공간","빵"]],["ChIJi_M445OkfDURBV_ePY2qCHo",37.5418384,127.0564636,"대림창고","정미소 창고를 갤러리 카페로. 전시를 보며 커피.",["갤러리"]]]},{"name":"안국","items":[["ChIJLXL2BvijfDURmTrYFPQIGUc",37.5776235,126.9865541,"어니언 안국","한옥 카페의 정석. 비 오는 날 기와 소리가 좋아요.",["한옥"]],["ChIJKw66zRCjfDURuaw9qYPdI-k",37.5791826,126.986152,"런던베이글뮤지엄 안국","커피보다 베이글. 줄이 길어요.",["웨이팅","빵"]]]},{"name":"한남","items":[["ChIJO_uFm7OjfDURH3ULjJYYuKg",37.5361018,127.000136,"앤트러사이트 한남","넓고 조용한 로스터리. 책 읽거나 노트북 하기 좋아요.",["로스터리","작업"]]]},{"name":"연남","items":[["ChIJH5tDs-WYfDURJGb8yuqKRwg",37.5662075,126.9192364,"경의선숲길(연남)","숲길 따라 작은 카페가 이어져요. 테이크아웃해서 걷기.",["산책"]]]}]},{"slug":"seoul-night-views","title":"서울 야경·노을 명소: 무료부터 전망대까지","desc":"해 질 무렵 가면 노을과 야경을 한 번에 볼 수 있는 곳들이에요. 대부분 무료이고, 전망대만 입장권이 있어요.","kind":"collection","themes":["서울","야경","노을","데이트"],"sections":[{"name":"무료","items":[["ChIJj1q-SjCjfDURrEOH3_cjrMM",37.5760794,127.0089876,"낙산공원 성곽길","성곽을 따라 걷다 보면 도심 야경이 펼쳐져요. 오르막이 있으니 편한 신발.",["무료","성곽"]],["ChIJkfry2i-ZfDURdkxPeBp8x7Q",37.5527919,126.8985613,"망원한강공원","한강에서 노을을 정면으로 보는 자리. 망원시장에서 먹을거리를 사 오면 완벽.",["노을","피크닉"]],["ChIJeVnK5X-hfDURv2fEEK-332M",37.5126335,126.9984783,"반포대교 달빛무지개분수","따뜻한 계절 저녁에 분수 쇼가 열려요. 가기 전에 운영 시간 확인.",["분수","계절 운영"]],["ChIJ8xRYr29FezUR3AtFqx2pIlw",37.5665256,127.0092236,"동대문디자인플라자","곡선 건물에 조명이 들어오는 밤이 더 멋져요.",["건축"]]]},{"name":"입장권","items":[["ChIJqWqOqFeifDURpYJ5LnxX-Fw",37.5511694,126.9882266,"남산서울타워","해 지기 1시간 전에 올라가 노을부터 야경까지. 내려올 땐 남산 산책로로 걸어서.",["노을","케이블카"]],["ChIJu7dpc45FezURhLMS5U5eaJk",37.5125295,127.102305,"서울스카이","롯데월드타워 꼭대기 층 전망대. 맑은 날을 고르세요.",["전망대","온라인 할인"]]]}]},{"slug":"busan-sea","title":"부산 바다 1박 2일: 해운대부터 태종대까지","desc":"첫날은 동쪽(해운대·광안리), 둘째 날은 서쪽(영도·남포) 바다로 나눴어요. 하루에 한쪽만 다녀야 이동이 짧아요.","kind":"course","themes":["부산","바다","1박2일","여행"],"sections":[{"name":"1일 · 동쪽 바다","items":[["ChIJXwf-DlyNaDURmKxjwdWxY5k",35.1586975,129.1603842,"해운대","아침 해변 산책. 동백섬까지 이어 걸어요.",["아침"]],["ChIJfdIYWwuNaDURDx-eqtUjCkg",35.158284,129.1727672,"해운대 블루라인파크(미포)","해변열차나 스카이캡슐로 바닷가를 따라가요. 캡슐은 미리 예약해야 해요.",["예약"]],["ChIJwabeuxuMaDURXC4Rb21AQaE",35.1884543,129.2231109,"해동용궁사","바닷가 바위 위의 절. 주말엔 일찍 가세요.",["일찍"]],["ChIJxw7HJy_taDUR-xaSTeHwbf8",35.1531696,129.118666,"광안리","해가 지면 광안대교 조명이 켜져요.",["야경"]]]},{"name":"2일 · 서쪽 바다","items":[["ChIJseGsfh7paDURigYilgTVojA",35.0782798,129.0453198,"흰여울문화마을","절벽 위 골목길과 바다 뷰 카페.",["골목"]],["ChIJOfX1e0zpaDURWq5Hp5x4-SM",35.05307,129.0872,"태종대","절벽과 등대. 다누비 열차를 타면 덜 걸어요.",["자연"]],["ChIJUToRo7fpaDURo_ZMItcBfpc",35.0973935,129.0105921,"감천문화마을","알록달록 언덕 마을. 스탬프 지도를 사서 따라가 보세요.",["스탬프"]]]}]},{"slug":"busan-food","title":"부산 먹거리: 시장과 노포 위주","desc":"남포동 일대에 몰려 있어서 하루에 다 돌 수 있어요.","kind":"collection","themes":["부산","맛집","시장"],"sections":[{"name":null,"items":[["ChIJudkrFArpaDURbbCzajeQs0c",35.0966339,129.0307965,"자갈치시장","1층에서 해산물을 고르고 2층 식당에서 바로 먹어요.",["해산물"]],["ChIJL1scg6DpaDURxXQZg1kWGZ4",35.098243,129.029212,"BIFF 광장","씨앗호떡은 여기서. 길거리 간식 골목이에요.",["씨앗호떡"]],["ChIJfYLMelSTaDURFlCRfk5W1PA",35.1013575,129.0281978,"국제시장","비빔당면 한 그릇. 골목이 미로 같아요.",["현금"]],["ChIJdRr5sgrpaDURcE3j03Uc7Tw",35.1008119,129.0301346,"개미집","낙곱새(낙지·곱창·새우) 전골. 점심 줄은 금방 빠져요.",["낙곱새"]],["ChIJ8VYk1e74IBURIIVPcKTynRI",35.1021046,129.0305985,"이재모피자","부산 사람들이 줄 서는 피자. 포장도 돼요.",["웨이팅","포장"]],["ChIJix8ZnTPtaDURA4tBnQ6w9PM",35.1541919,129.1270348,"밀락더마켓","광안리 실내 마켓. 광안대교 보면서 저녁.",["실내"]]]}]},{"slug":"jeju-east","title":"제주 동쪽 하루: 일출봉, 우도, 용암동굴","desc":"성산일출봉 일출로 시작해 동쪽 해안을 따라 제주시로 돌아오는 하루예요. 차가 있으면 편해요.","kind":"course","themes":["제주","자연","하루코스"],"sections":[{"name":null,"items":[["ChIJn3jj9rkUDTURS7YjOgUyUVU",33.458056,126.9425,"성산일출봉","일출을 보려면 해 뜨기 40분 전에는 오르기 시작하세요. 정상까지 20~30분.",["일출"]],["ChIJA_du00wVDTURisfAXXmN2fQ",33.5042977,126.954048,"우도","성산항에서 배로 들어가 전기자전거로 한 바퀴. 날씨가 나쁘면 배편을 확인하세요.",["배편 확인"]],["ChIJxR5oOuwXDTUR7OVyfNv5QT4",33.5559739,126.7961709,"월정리해변","맑은 물빛과 풍력발전기, 바다 앞 카페들.",["카페"]],["ChIJmWohlsQZDTURppUrDPCrZrs",33.5281972,126.7717618,"만장굴","용암동굴 약 1km를 걸어요. 안은 1년 내내 서늘해 겉옷 필수.",["겉옷"]],["ChIJISh-Xu0DDTUROxfzWeIn6Qg",33.3949678,126.6839679,"사려니숲길","삼나무 숲길. 비 오는 날 더 좋아요.",["숲"]],["ChIJVSv3qq_8DDURcLh4pWxZ0vA",33.5434231,126.6697752,"함덕해수욕장","하루 마무리 노을. 바로 앞에 델문도 카페.",["노을"]]]}]},{"slug":"jeju-west","title":"제주 서쪽 & 시내: 녹차밭, 에메랄드 바다, 흑돼지","desc":"서귀포 폭포에서 시작해 서쪽 해안을 돌고 제주시에서 저녁을 먹는 코스예요.","kind":"course","themes":["제주","맛집","바다"],"sections":[{"name":null,"items":[["ChIJhYbR5ZdTDDURtgGb2uZzuA0",33.246944,126.554417,"천지연폭포","평탄한 산책로로 폭포까지. 저녁엔 조명이 켜져요.",["산책"]],["ChIJEczrGRJdDDUR0cpD2okSp7g",33.3059385,126.2894355,"오설록 티뮤지엄","녹차밭 구경하고 녹차 디저트.",["녹차"]],["ChIJ8bBzwwBhDDURAISiRyzO4mw",33.3942945,126.2398813,"협재해수욕장","에메랄드빛 물과 비양도 풍경.",["바다"]],["ChIJywNUk1LjDDURflXUtmnWhIo",33.498621,126.4587659,"자매국수","제주 고기국수. 식사 시간엔 대기가 있어요.",["웨이팅"]],["ChIJFfbe5lbjDDUR3WjCTurWe20",33.5154245,126.5268573,"흑돼지거리","흑돼지 구이 저녁. 가게가 줄지어 있어요.",["저녁"]],["ChIJpyFxA1TjDDUR1kddP-9mN0Y",33.5122122,126.5282021,"동문재래시장","저녁에 야시장이 열려요. 귤과 기념품도.",["야시장"]]]}]},{"slug":"tokyo-4days","title":"도쿄 3박 4일: 처음 가는 사람용 기본 코스","desc":"하루에 한 동네씩 묶어서 이동을 줄였어요. 1일 아사쿠사·우에노, 2일 하라주쿠·시부야, 3일 쓰키지·도요스, 4일 신주쿠·서쪽 동네.","kind":"course","themes":["도쿄","일본","여행","3박4일"],"sections":[{"name":"1일 · 아사쿠사·우에노","items":[["ChIJ8T1GpMGOGGARDYGSgpooDWw",35.7147651,139.7966553,"센소지","아침 8시 전에 가면 한산해요.",["아침 일찍"]],["ChIJ35ov0dCOGGARKvdDH7NPHX0",35.7100627,139.8107004,"도쿄 스카이트리","맑은 날엔 후지산이 보이기도 해요.",["전망"]],["ChIJh7eDrwCPGGARCs9fpCkKS2U",35.7100682,139.7746009,"아메요코 시장","과일 꼬치와 길거리 간식.",["간식"]]]},{"name":"2일 · 하라주쿠·시부야","items":[["ChIJ5SZMmreMGGARcz8QSTiJyo8",35.6763976,139.6993259,"메이지 신궁","하라주쿠역 바로 옆 숲속 신사.",["무료"]],["ChIJK9EM68qLGGARacmu4KJj5SA",35.659482,139.7005596,"시부야 스크램블 교차로","한 번 건너 보고, 위에서 내려다보기.",["명소"]],["ChIJ4Rr2JWiLGGARcyRSHuZ-9G8",35.6586719,139.7019848,"시부야 스카이","해 질 녘 시간대로 미리 예약하세요.",["예약 필수"]],["ChIJOWucdKiMGGARbppa4b4CKA8",35.6611185,139.7009846,"이치란 시부야","칸막이 1인석 돈코츠 라멘, 늦게까지 해요.",["혼밥"]]]},{"name":"3일 · 쓰키지·도요스","items":[["ChIJW2cLzSGLGGARXAKXv6EkbqI",35.6647703,139.7702515,"쓰키지 장외시장","달걀말이, 참치, 꼬치로 아침. 일찍, 현금 챙기기.",["현금"]],["ChIJSeco5wiJGGARItbTS8lQ5G0",35.6491207,139.7897739,"팀랩 플래닛","맨발로 물속을 걷는 전시. 걷어 올릴 수 있는 바지로.",["예약 필수"]],["ChIJVVVp3BaJGGARfAgSR2yEybw",35.6777557,139.8005894,"블루보틀 기요스미시라카와","블루보틀 일본 1호점.",["커피"]]]},{"name":"4일 · 신주쿠·서쪽 동네","items":[["ChIJPyOTG8KMGGARh_IXobWxHmo",35.6851763,139.7100517,"신주쿠 교엔","일본·프랑스·영국식 정원이 한곳에. 월요일 휴무, 입장료 있어요.",["월 휴무"]],["ChIJVVUBmZ_zGGARrEy-Ua3psAY",35.6488124,139.647481,"고토쿠지","하얀 마네키네코 수천 개가 모인 절.",["고양이"]],["ChIJw_teZ_8hGGARgsSeLR2OLjM",35.665786,139.6698627,"시모키타자와","빈티지 옷가게와 레코드숍.",["빈티지"]],["ChIJ508frs-MGGARnIKrb_tkai0",35.6868343,139.6966393,"후운지","진한 츠케멘. 줄은 길어도 빨리 빠져요.",["웨이팅"]],["ChIJP9eKBdeMGGAR0zzBXJNVj5A",35.6927037,139.6995778,"오모이데요코초","신주쿠역 옆 꼬치 골목. 좁으니 2명이 좋아요.",["야키토리"]]]}]},{"slug":"vlog-gangneung-day-trip","title":"[브이로그] 강릉 당일치기: 바다, 커피, 순두부","desc":"여행 브이로그처럼 짠 코스예요. 섹션은 '에피소드', 메모는 촬영 콘티처럼 썼어요.\n서울역·청량리역에서 KTX로 2시간 안팎이라 당일치기로 충분해요. PinWith에서는 장소마다 유튜브 영상의 특정 시간을 붙일 수 있으니, 직접 찍었다면 내 영상 타임라인을 달아 공유해 보세요.","kind":"course","themes":["강릉","브이로그","당일치기","바다","커피"],"sections":[{"name":"EP.1 · 도착, 순두부 아침","items":[["ChIJy_1lrJfmYTUR0PnAEqOIgxM",37.7925599,128.9170172,"초당순두부마을","▶ 오프닝: 김 나는 순두부 클로즈업. 바닷물로 간수를 해 만든다는 이 동네 순두부 이야기를 자막으로.",["아침","순두부"]],["ChIJKQ8jYrnlYTURKf8PKysmjgA",37.7792353,128.8775226,"오죽헌","▶ 율곡 이이가 태어난 곳. 검은 대나무(오죽) 숲 앞에서 5천 원·5만 원 지폐 속 인물 이야기 한 컷.",["역사"]]]},{"name":"EP.2 · 바다와 커피","items":[["ChIJXwO_GQvkYTUR9WEkQrhVmbI",37.8224255,128.884808,"테라로사 사천","▶ 북쪽에서 시작: 소나무 숲 건너 바다가 보이는 로스터리. 첫 커피와 원두 고르는 장면.",["로스터리"]],["ChIJAUtHQ6bmYTURw9bnPeplAtM",37.8054863,128.9078306,"경포해변","▶ 남쪽으로 내려오며 방파제에서 와이드 샷. 바람 소리 그대로 살리기.",["바다"]],["ChIJ70y4vL3mYTURsw4SBNF1HJY",37.7948358,128.9193758,"강문해변","▶ 경포에서 걸어서 이어지는 작은 해변. 해변 카페 창가 자리 브이로그.",["카페"]],["ChIJb4_vGlfnYTURZKvnWLBhDpY",37.7723486,128.9476577,"안목해변 커피거리","▶ 메인 장면: 바다 앞 카페 거리. 테이크아웃 컵 들고 걷는 컷으로 에피소드 마무리.",["커피거리"]]]},{"name":"EP.3 · 시장 먹방, 귀가","items":[["ChIJ5-y4g_vlYTURGd4LueRcB1E",37.7539884,128.8986105,"강릉중앙시장","▶ 먹방 몽타주: 오징어순대, 닭강정, 감자전. 기차 시간 전에 포장까지.",["먹방","포장"]],["ChIJ9agJutHiYTURSC6sARVkuiY",37.8910576,128.8277523,"주문진수산시장","▶ 시간이 남으면 보너스: 대게·홍게 수조 구경. 고른 해산물을 바로 쪄 주는 식당이 붙어 있어요.",["보너스"]]]}]}]$json$::jsonb;
  rec jsonb; sec jsonb; it jsonb; lid uuid; sid uuid; pos int; si int;
begin
  for rec in select * from jsonb_array_elements(doc) loop
    continue when exists (select 1 from public.lists where owner_id = o and slug = rec->>'slug');
    insert into public.lists (owner_id, slug, title, description, visibility, kind, themes, is_example)
    values (o, rec->>'slug', rec->>'title', rec->>'desc', 'public', (rec->>'kind')::public.list_kind,
            array(select jsonb_array_elements_text(rec->'themes')), true)
    returning id into lid;
    pos := 0; si := 0;
    for sec in select * from jsonb_array_elements(rec->'sections') loop
      sid := null;
      if sec->>'name' is not null then
        insert into public.sections (list_id, name, position) values (lid, sec->>'name', si) returning id into sid;
      end if;
      for it in select * from jsonb_array_elements(sec->'items') loop
        insert into public.places (google_place_id, lat, lng, coords_fetched_at)
        values (it->>0, (it->>1)::float8, (it->>2)::float8, now()) on conflict (google_place_id) do nothing;
        insert into public.list_items (list_id, section_id, place_id, position, added_by, custom_title, memo, tags)
        values (lid, sid, it->>0, pos, o, it->>3, it->>4, array(select jsonb_array_elements_text(it->5)));
        pos := pos + 1;
      end loop;
      si := si + 1;
    end loop;
  end loop;
end $seed$;
